import {connect} from 'react-redux'

import type {State} from '../../../../../reducers/types'
import {getBuild} from '../../../../../selectors'

import BuildLogOverviewDuration from './BuildLogOverviewDuration'
import type {OwnProps, StateProps} from './BuildLogOverviewDuration.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const build = getBuild(state, props.buildId)
  return {
    startDate: build?.startDate,
    finishDate: build?.finishDate,
  }
}

export default connect(mapStateToProps, {})(BuildLogOverviewDuration)
