import classNames from 'classnames'
import * as React from 'react'
import {useLazyLoadQuery} from 'react-relay'

import BuildLineLayout from '../../../../../containers/BuildLineLayout'
import BuildsFetcher from '../../../../../containers/BuildsFetcher'
import OneLineDetector from '../../../../../containers/OneLineDetector'
import {useSyncedBooleanQueryParam} from '../../../../../hooks/routes'
import {stringifyId} from '../../../../../types'
import {UserProperties} from '../../../../../utils/userProperties'
import {useBuildsClassName} from '../../../../common/Builds/Builds'
import ContentPanel from '../../../../common/ContentPanel/ContentPanel'
import Grid from '../../../../common/Grid/Grid'
import {useSequenceLoaderReadyHandler} from '../../../../common/SequenceLoader/SequenceLoader.hooks'

import type {DeploymentsQuery} from './__generated__/DeploymentsQuery.graphql'
import Deployment from './Deployment/Deployment.container'
import {useDeployments} from './Deployments.hooks'
import {deploymentsQuery, getDeploymentsQueryVariables} from './Deployments.queries'
import {getDeploymentsLocator} from './Deployments.rest'
import type {
  DeploymentsProps,
  DeploymentGridProps,
  WrapperDeploymentsProps,
} from './Deployments.types'

import styles from './Deployments.module.css'

function WrapperDeployments({
  possibleSnapshotDeploymentsKey,
  possibleArtifactDeploymentsKey,
  buildId,
  buildTypeId,
}: WrapperDeploymentsProps) {
  const {possibleSnapshotDeploymentsSet, order, isReady} = useDeployments(
    possibleSnapshotDeploymentsKey,
    possibleArtifactDeploymentsKey,
  )

  useSequenceLoaderReadyHandler(isReady)

  if (!order.length) {
    return null
  }

  return (
    <BuildsFetcher locator={getDeploymentsLocator(buildId)} withQueued withBuildDetails>
      <OneLineDetector>
        <BuildLineLayout showPath={false}>
          <DeploymentGrid>
            {order.map(id => (
              <Deployment
                key={stringifyId(id)}
                buildId={buildId}
                buildTypeId={buildTypeId}
                deployTypeId={id}
                artifactOnly={!possibleSnapshotDeploymentsSet.has(id)}
              />
            ))}
          </DeploymentGrid>
        </BuildLineLayout>
      </OneLineDetector>
    </BuildsFetcher>
  )
}

function DeploymentGrid({children}: DeploymentGridProps) {
  return <Grid className={classNames(styles.grid, useBuildsClassName())}>{children}</Grid>
}

function Deployments({buildId, buildTypeId}: DeploymentsProps) {
  const panelType = UserProperties.EXPAND_BUILD_DEPLOYMENTS_SECTION
  const [isExpandedDeploymentsSection] = useSyncedBooleanQueryParam({
    param: panelType,
    userProperty: panelType,
    skip: true,
  })
  const isExpandedSectionRef = React.useRef(isExpandedDeploymentsSection)
  const isExpandedSection = isExpandedDeploymentsSection || isExpandedSectionRef.current
  const {possibleSnapshotDeployments = null, possibleArtifactDeployments = null} =
    useLazyLoadQuery<DeploymentsQuery>(deploymentsQuery, getDeploymentsQueryVariables(buildTypeId))
  const hasBuildTypes = possibleSnapshotDeployments?.count || possibleArtifactDeployments?.count

  useSequenceLoaderReadyHandler(true)

  React.useEffect(() => {
    if (isExpandedDeploymentsSection) {
      isExpandedSectionRef.current = isExpandedDeploymentsSection
    }
  }, [isExpandedDeploymentsSection])

  if (!hasBuildTypes) {
    return null
  }

  return (
    <ContentPanel
      panelType={panelType}
      heading="Deployments"
      withBorder={false}
      content={
        isExpandedSection ? (
          <WrapperDeployments
            possibleSnapshotDeploymentsKey={possibleSnapshotDeployments}
            possibleArtifactDeploymentsKey={possibleArtifactDeployments}
            buildId={buildId}
            buildTypeId={buildTypeId}
          />
        ) : null
      }
    />
  )
}

export default Deployments
