import Link from '@jetbrains/ring-ui-built/components/link/link'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import * as React from 'react'

import {stringifyId} from '../../../../../types'

import type {Props} from './ViewThreadDumpButton.types'

import styles from './ViewThreadDumpButton.module.css'

function ViewThreadDumpButton({agentId, projectId, className}: Props) {
  return (
    <Link
      href={resolveRelative(
        `/stacktraces/stacktrace.html?agentId=${stringifyId(agentId)}&projectId=${stringifyId(
          projectId,
        )}`,
      )}
      className={classNames(className, styles.link)}
      target="_blank"
      rel="noreferrer"
    >
      {'View thread dump'}
    </Link>
  )
}

export default React.memo(ViewThreadDumpButton)
