import * as React from 'react'
import {graphql, useFragment} from 'react-relay'

import {notNull} from '../../../../../utils/guards'

import type {DeploymentsFragment$key} from './__generated__/DeploymentsFragment.graphql'

const fragment = graphql`
  fragment DeploymentsFragment on BuildTypes {
    buildType {
      id
      name
      project {
        id
        name
        ancestorProjects {
          project {
            id
            name
          }
        }
      }
    }
  }
`

type ArrayElement<A> = A extends readonly (infer T)[] ? T : never

export const useDeployments = (
  possibleSnapshotDeploymentsKey: DeploymentsFragment$key | null,
  possibleArtifactDeploymentsKey: DeploymentsFragment$key | null,
) => {
  const possibleArtifactDeploymentsBuildType = useFragment(
    fragment,
    possibleArtifactDeploymentsKey,
  )?.buildType
  const possibleSnapshotDeploymentsBuildType = useFragment(
    fragment,
    possibleSnapshotDeploymentsKey,
  )?.buildType

  type BuildType = ArrayElement<typeof possibleArtifactDeploymentsBuildType>

  const possibleSnapshotDeploymentsSet = React.useMemo(
    () => new Set(possibleSnapshotDeploymentsBuildType?.map(({id}) => id)),
    [possibleSnapshotDeploymentsBuildType],
  )

  const extractNames = React.useCallback((item: BuildType) => {
    const ancestorProjects =
      item?.project?.ancestorProjects?.project?.map(project => project.name) || []
    const currentProject = item?.project?.name
    const buildType = item?.name
    return [...ancestorProjects, currentProject, buildType].filter(
      name => name !== undefined,
    ) as string[]
  }, [])

  const compareNames = (a: string[], b: string[]) => {
    for (let i = 0; i < Math.max(a.length, b.length); i++) {
      if (a[i] === undefined) {
        return -1
      }
      if (b[i] === undefined) {
        return 1
      }
      if (a[i] < b[i]) {
        return -1
      }
      if (a[i] > b[i]) {
        return 1
      }
    }
    return 0
  }

  const order = React.useMemo(() => {
    const deployments = [
      ...(possibleArtifactDeploymentsBuildType || []),
      ...(possibleSnapshotDeploymentsBuildType || []),
    ]

    const sortedDeployments = deployments
      .sort((a, b) => compareNames(extractNames(a), extractNames(b)))
      .filter((deployment, index, self) => index === self.findIndex(d => d.id === deployment.id))

    return sortedDeployments.map(({id}) => id).filter(notNull)
  }, [possibleArtifactDeploymentsBuildType, possibleSnapshotDeploymentsBuildType, extractNames])

  return {
    isReady:
      possibleArtifactDeploymentsBuildType != null && possibleSnapshotDeploymentsBuildType != null,
    possibleSnapshotDeploymentsSet,
    order,
  }
}
