import compose from 'lodash/flowRight'
import {connect} from 'react-redux'
import type {EntryPointProps} from 'react-relay'

import withStatusSubscription from '../../../../hocs/withStatusSubscription'
import type {State} from '../../../../reducers/types'
import {getBuild, getBuildType} from '../../../../selectors'
import {parseBranch} from '../../../../utils/branchNames'
import type {SnapshotDependenciesCountersQuery} from '../../../common/BuildInfoTable/SnapshotDependenciesCounters/__generated__/SnapshotDependenciesCountersQuery.graphql'
import type {BuildProblemsPreviewQuery} from '../../../packages/BuildProblems/BuildProblemsPreview/__generated__/BuildProblemsPreviewQuery.graphql'
import type {TestsPreviewPanelCountsQuery} from '../../../packages/Tests/TestsPreviewPanel/__generated__/TestsPreviewPanelCountsQuery.graphql'

import BuildOverviewTab from './BuildOverviewTab'
import type {OuterProps, OwnProps, StateProps} from './BuildOverviewTab.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const {buildId} = props
  const build = getBuild(state, buildId)
  const branch = !build?.defaultBranch ? parseBranch(build?.branchName) : null
  const buildType = getBuildType(state, build?.buildType)
  return {
    branch,
    buildTypeId: build?.buildType,
    buildTypeInternalId: buildType?.internalId,
    queued: build?.state === 'queued',
    finished: build?.state === 'finished',
    composite: build?.composite ?? false,
  }
}

const connector = connect(mapStateToProps)

const BuildOverviewTabContainer = compose(connector, withStatusSubscription())(BuildOverviewTab)
type Queries = {
  testCounts: TestsPreviewPanelCountsQuery
  snapshotDependenciesCounters: SnapshotDependenciesCountersQuery
  buildProblemsPreview: BuildProblemsPreviewQuery
}
export default function BuildOverviewTabOuterContainer({
  queries,
  props,
}: EntryPointProps<Queries, {}, OuterProps, {}>) {
  return (
    <BuildOverviewTabContainer
      {...props}
      testCountsQuery={queries.testCounts}
      snapshotDependenciesCountersQuery={queries.snapshotDependenciesCounters}
      buildProblemsPreviewQuery={queries.buildProblemsPreview}
    />
  )
}
export type BuildOverviewTabOuterContainerComponent = typeof BuildOverviewTabOuterContainer
