import {connect} from 'react-redux'

import type {State} from '../../../../reducers/types'
import {getBuild} from '../../../../selectors'

import BuildLogOverview from './BuildLogOverview'
import type {OwnProps, StateProps} from './BuildLogOverview.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const build = getBuild(state, props.buildId)
  return {
    running: build?.state === 'running',
  }
}

export default connect(mapStateToProps, {})(BuildLogOverview)
